<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<article class="ps-coa-history-previous ps-coa-history-previous--<?php echo esc_attr( $report['public_status_tone'] ); ?>">
	<div class="ps-coa-history-previous__identity"><p class="ps-coa-eyebrow"><?php esc_html_e( 'Previous Batch', 'pepselect-coa-archive' ); ?></p><h3><?php echo esc_html( $report['batch_number'] ); ?></h3><p><?php echo esc_html( sprintf( __( 'Tested %s', 'pepselect-coa-archive' ), $report['test_date_label'] ?: '—' ) ); ?><br><?php echo esc_html( $report['laboratory'] ?: '—' ); ?><br><?php echo esc_html( $report['history_report_type'] ); ?></p><span class="ps-coa-history-status-pill"><?php echo esc_html( $report['history_status_label'] ); ?></span></div>
	<div class="ps-coa-history-previous__results"><dl><div><dt><?php esc_html_e( 'Purity', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['purity_percentage_display'] ? esc_html( $report['purity_percentage_display'] . '%' ) : '—'; ?></dd></div><div><dt><?php esc_html_e( 'Average Net Content', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['average_net_content_display'] ? esc_html( trim( $report['average_net_content_display'] . ' ' . $report['content_unit'] ) ) : '—'; ?></dd></div><div><dt><?php esc_html_e( 'Labeled Content', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['claimed_content_display'] ? esc_html( trim( $report['claimed_content_display'] . ' ' . $report['content_unit'] ) ) : '—'; ?></dd></div><div><dt><?php esc_html_e( 'Vials Tested', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $report['vials_tested_display'] ? esc_html( $report['vials_tested_display'] ) : '—'; ?></dd></div></dl><ul><?php foreach ( $report['qc_strip_rows'] as $row ) : if ( ! in_array( $row['key'], array( 'identity', 'heavy-metals', 'sterility', 'endotoxins', 'fentanyl' ), true ) ) { continue; } ?><li class="<?php echo ! $row['reported'] ? 'is-neutral' : ( ! empty( $row['status']['success'] ) ? 'is-success' : 'is-failed' ); ?>"><span aria-hidden="true"><?php echo ! $row['reported'] ? '—' : ( ! empty( $row['status']['success'] ) ? '✓' : '!' ); ?></span><strong><?php echo esc_html( $row['short_label'] ); ?></strong><small><?php echo esc_html( $row['reported'] ? $row['detail'] : '--' ); ?></small></li><?php endforeach; ?></ul></div>
	<div class="ps-coa-history-previous__actions"><p><?php echo esc_html( $report['history_context'] ); ?></p><a class="ps-coa-button ps-coa-button--secondary" href="<?php echo esc_url( $report['detail_url'] ); ?>"><?php esc_html_e( 'View Full Report', 'pepselect-coa-archive' ); ?> <span aria-hidden="true">›</span></a><?php if ( $report['pdf_url'] ) : ?><a class="ps-coa-history-pdf" href="<?php echo esc_url( $report['pdf_url'] ); ?>" target="_blank" rel="noopener noreferrer"><?php esc_html_e( 'Original PDF', 'pepselect-coa-archive' ); ?><span class="screen-reader-text"><?php esc_html_e( ' (opens in a new tab)', 'pepselect-coa-archive' ); ?></span></a><?php endif; ?></div>
</article>
